    "BeforeJson" text,
    "AfterJson" text,
    "IpAddress" character varying(80),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_audit_logs" PRIMARY KEY ("Id")
);

