CREATE TABLE advance.tax_gst_settings (
    "Id" uuid NOT NULL,
    "OrganizationId" character varying(100) NOT NULL,
    "JurisdictionCode" character varying(30) NOT NULL,
    "HsnSacCode" character varying(30) NOT NULL,
    "SupplyType" character varying(30) NOT NULL,
    "SupplierStateCode" character varying(10) NOT NULL,
    "PlaceOfSupplyStateCode" character varying(10) NOT NULL,
    "VendorRegistrationType" character varying(30) NOT NULL,
    "GstRate" numeric(9,6) NOT NULL,
    "CgstRate" numeric(9,6) NOT NULL,
    "SgstRate" numeric(9,6) NOT NULL,
    "IgstRate" numeric(9,6) NOT NULL,
    "CessRate" numeric(9,6) NOT NULL,
    "IsExempt" boolean NOT NULL,
    "IsReverseCharge" boolean NOT NULL,
    "CurrencyCode" character varying(3) NOT NULL,
    "RoundingScale" integer NOT NULL,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    "ApprovalStatus" character varying(50) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_tax_gst_settings" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_tax_gst_component_split" CHECK (("SupplyType" = 'INTRASTATE' AND "IgstRate" = 0 AND "CgstRate" + "SgstRate" = "GstRate") OR ("SupplyType" = 'INTERSTATE' AND "CgstRate" = 0 AND "SgstRate" = 0 AND "IgstRate" = "GstRate")),
    CONSTRAINT "CK_tax_gst_dates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
    CONSTRAINT "CK_tax_gst_rates" CHECK ("GstRate" BETWEEN 0 AND 100 AND "CgstRate" BETWEEN 0 AND 100 AND "SgstRate" BETWEEN 0 AND 100 AND "IgstRate" BETWEEN 0 AND 100 AND "CessRate" BETWEEN 0 AND 100),
    CONSTRAINT "CK_tax_gst_rounding" CHECK ("RoundingScale" BETWEEN 0 AND 6),
    CONSTRAINT "CK_tax_gst_state_supply" CHECK (("SupplierStateCode" = "PlaceOfSupplyStateCode" AND "SupplyType" = 'INTRASTATE') OR ("SupplierStateCode" <> "PlaceOfSupplyStateCode" AND "SupplyType" = 'INTERSTATE')),
    CONSTRAINT "CK_tax_gst_supply_type" CHECK ("SupplyType" IN ('INTRASTATE','INTERSTATE'))
);

