    CONSTRAINT "CK_uom_conversion_dates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
    CONSTRAINT "CK_uom_conversion_distinct" CHECK ("FromUomId" <> "ToUomId"),
    CONSTRAINT "CK_uom_conversion_factor" CHECK ("ConversionFactor" > 0),
    CONSTRAINT "CK_uom_conversion_precision" CHECK ("QuantityPrecision" = 6),
    CONSTRAINT "FK_uom_conversions_uoms_FromUomId" FOREIGN KEY ("FromUomId") REFERENCES advance.uoms ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_uom_conversions_uoms_ToUomId" FOREIGN KEY ("ToUomId") REFERENCES advance.uoms ("Id") ON DELETE RESTRICT
);

