CREATE TABLE advance.purchase_requisition_lines (
    "Id" uuid NOT NULL,
    "PurchaseRequisitionId" uuid NOT NULL,
    "LineNumber" integer NOT NULL,
    "ItemId" uuid,
    "ItemCodeSnapshot" character varying(80) NOT NULL,
    "ItemNameSnapshot" character varying(240) NOT NULL,
    "UomSnapshot" character varying(32) NOT NULL,
    "SpecificationSnapshot" character varying(2000),
    "RequestedQuantity" numeric(18,3) NOT NULL,
    "EstimatedUnitPriceSnapshot" numeric(18,2) NOT NULL,
    "EstimatedLineTotal" numeric(18,2) NOT NULL,
    "RequiredDate" date NOT NULL,
    "PreferredWarehouseId" uuid,
    "ProjectReference" character varying(160),
    "MachineReference" character varying(160),
    "ServiceReference" character varying(160),
    "OnHandSnapshot" numeric(18,3) NOT NULL,
    "ActiveReservedSnapshot" numeric(18,3) NOT NULL,
    "AvailableSnapshot" numeric(18,3) NOT NULL,
    "InTransitSnapshot" numeric(18,3) NOT NULL,
    "StockCheckedAt" timestamp with time zone,
    "ReservedQuantity" numeric(18,3) NOT NULL,
    "ShortageQuantity" numeric(18,3) NOT NULL,
    "ProcurementHandoffQuantity" numeric(18,3) NOT NULL,
    "LineStatus" character varying(60) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_purchase_requisition_lines" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_pr_lines_amounts_nonnegative" CHECK ("EstimatedUnitPriceSnapshot" >= 0 AND "EstimatedLineTotal" >= 0 AND "ReservedQuantity" >= 0 AND "ShortageQuantity" >= 0 AND "ProcurementHandoffQuantity" >= 0),
    CONSTRAINT "CK_pr_lines_reconcile_requested" CHECK ("ReservedQuantity" <= "RequestedQuantity" AND "ShortageQuantity" = GREATEST("RequestedQuantity" - "ReservedQuantity", 0) AND "ProcurementHandoffQuantity" = "ShortageQuantity"),
    CONSTRAINT "CK_pr_lines_requested_qty_positive" CHECK ("RequestedQuantity" > 0),
