    CONSTRAINT "PK_vendor_quotation_lines" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_vendor_quotation_line_quantity" CHECK ("Quantity" > 0),
    CONSTRAINT "CK_vendor_quotation_line_values" CHECK ("UnitRate" >= 0 AND "DiscountValue" >= 0 AND "HeaderDiscountValue" >= 0 AND "PackingForwarding" >= 0 AND "Freight" >= 0 AND "Insurance" >= 0 AND "OtherCharges" >= 0 AND "TaxableValue" >= 0 AND "CgstValue" >= 0 AND "SgstValue" >= 0 AND "IgstValue" >= 0 AND "CessValue" >= 0 AND "TotalPayableValue" >= 0),
    CONSTRAINT "FK_vendor_quotation_lines_request_for_quotation_lines_RequestF~" FOREIGN KEY ("RequestForQuotationLineId") REFERENCES advance.request_for_quotation_lines ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_vendor_quotation_lines_tax_gst_settings_TaxGstSettingId" FOREIGN KEY ("TaxGstSettingId") REFERENCES advance.tax_gst_settings ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_vendor_quotation_lines_vendor_quotations_VendorQuotationId" FOREIGN KEY ("VendorQuotationId") REFERENCES advance.vendor_quotations ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.purchase_orders (
    "Id" uuid NOT NULL,
    "OrganizationId" character varying(100) NOT NULL,
    "PoNumber" character varying(64) NOT NULL,
    "FinancialYear" character varying(12) NOT NULL,
    "SequenceNumber" bigint NOT NULL,
    "RootPurchaseOrderId" uuid NOT NULL,
    "PreviousVersionId" uuid,
    "RevisionNumber" integer NOT NULL,
    "IsCurrentVersion" boolean NOT NULL,
    "CommercialComparisonId" uuid NOT NULL,
    "VendorId" uuid NOT NULL,
    "RequestingDepartmentId" uuid,
    "DeliveryWarehouseId" uuid,
    "OwnerEmployeeId" uuid NOT NULL,
    "Status" character varying(40) NOT NULL,
    "CurrencyCode" character varying(3) NOT NULL,
    "ApprovalRoute" character varying(40) NOT NULL,
    "TaxableValue" numeric(24,6) NOT NULL,
    "DiscountValue" numeric(24,6) NOT NULL,
    "HeaderDiscountValue" numeric(24,6) NOT NULL,
    "TaxValue" numeric(24,6) NOT NULL,
    "PackingForwarding" numeric(24,6) NOT NULL,
    "Freight" numeric(24,6) NOT NULL,
    "Insurance" numeric(24,6) NOT NULL,
    "OtherCharges" numeric(24,6) NOT NULL,
    "RoundOff" numeric(24,6) NOT NULL,
    "TotalPayableValue" numeric(24,6) NOT NULL,
    "ApprovalPolicySnapshotJson" jsonb NOT NULL,
    "PaymentTermsSnapshot" character varying(2000) NOT NULL,
    "DeliveryTermsSnapshot" character varying(2000) NOT NULL,
    "WarrantyTermsSnapshot" character varying(2000) NOT NULL,
    "AmendmentReason" character varying(2000),
    "IssuedAt" timestamp with time zone,
    "CancelledAt" timestamp with time zone,
    "CancellationReason" character varying(2000),
    "IdempotencyKey" character varying(200) NOT NULL,
    "TransitionCorrelationId" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_purchase_orders" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_purchase_order_cancel_reason" CHECK ("Status" <> 'Cancelled' OR ("CancelledAt" IS NOT NULL AND length(trim(coalesce("CancellationReason", ''))) > 0)),
    CONSTRAINT "CK_purchase_order_current_lifecycle" CHECK ("Status" <> 'Superseded' OR NOT "IsCurrentVersion"),
    CONSTRAINT "CK_purchase_order_revision" CHECK ("RevisionNumber" > 0 AND "SequenceNumber" > 0),
    CONSTRAINT "CK_purchase_order_status" CHECK ("Status" IN ('Draft','PendingApproval','Approved','Issued','Rejected','RevisionDraft','Resubmitted','Superseded','Cancelled')),
    CONSTRAINT "CK_purchase_order_values" CHECK ("TaxableValue" >= 0 AND "DiscountValue" >= 0 AND "HeaderDiscountValue" >= 0 AND "TaxValue" >= 0 AND "PackingForwarding" >= 0 AND "Freight" >= 0 AND "Insurance" >= 0 AND "OtherCharges" >= 0 AND "TotalPayableValue" >= 0 AND "ApprovalPolicySnapshotJson" <> '{}'::jsonb),
    CONSTRAINT "FK_purchase_orders_commercial_comparisons_CommercialComparison~" FOREIGN KEY ("CommercialComparisonId") REFERENCES advance.commercial_comparisons ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_departments_RequestingDepartmentId" FOREIGN KEY ("RequestingDepartmentId") REFERENCES advance.departments ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_employees_OwnerEmployeeId" FOREIGN KEY ("OwnerEmployeeId") REFERENCES advance.employees ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_purchase_orders_PreviousVersionId" FOREIGN KEY ("PreviousVersionId") REFERENCES advance.purchase_orders ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_vendors_VendorId" FOREIGN KEY ("VendorId") REFERENCES advance.vendors ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_warehouses_DeliveryWarehouseId" FOREIGN KEY ("DeliveryWarehouseId") REFERENCES advance.warehouses ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.purchase_transaction_approval_history (
    "Id" uuid NOT NULL,
    "CommercialComparisonId" uuid NOT NULL,
    "Action" character varying(50) NOT NULL,
    "FromStatus" character varying(40) NOT NULL,
    "ToStatus" character varying(40) NOT NULL,
    "ApprovalRoute" character varying(40) NOT NULL,
    "ActorEmployeeId" uuid NOT NULL,
    "ActorLoginId" character varying(256) NOT NULL,
    "ActorRoleCode" character varying(100) NOT NULL,
    "Remarks" character varying(2000) NOT NULL,
    "CorrelationId" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_purchase_transaction_approval_history" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_purchase_approval_history_remarks" CHECK (length(trim("Remarks")) > 0),
    CONSTRAINT "FK_purchase_transaction_approval_history_commercial_comparison~" FOREIGN KEY ("CommercialComparisonId") REFERENCES advance.commercial_comparisons ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_transaction_approval_history_employees_ActorEmploy~" FOREIGN KEY ("ActorEmployeeId") REFERENCES advance.employees ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.commercial_comparison_lines (
    "Id" uuid NOT NULL,
    "CommercialComparisonId" uuid NOT NULL,
    "VendorQuotationLineId" uuid NOT NULL,
    "VendorId" uuid NOT NULL,
    "TechnicalComplianceSnapshot" character varying(40) NOT NULL,
    "CommercialSnapshotJson" jsonb NOT NULL,
    "DeliverySnapshot" character varying(2000) NOT NULL,
    "WarrantySnapshot" character varying(2000) NOT NULL,
    "PaymentTermsSnapshot" character varying(2000) NOT NULL,
    "TotalPayableValue" numeric(24,6) NOT NULL,
    "IsRecommended" boolean NOT NULL,
    "RecommendationReason" character varying(2000),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_commercial_comparison_lines" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_comparison_line_total" CHECK ("TotalPayableValue" >= 0 AND (NOT "IsRecommended" OR length(trim(coalesce("RecommendationReason", ''))) > 0)),
    CONSTRAINT "FK_commercial_comparison_lines_commercial_comparisons_Commerci~" FOREIGN KEY ("CommercialComparisonId") REFERENCES advance.commercial_comparisons ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_commercial_comparison_lines_vendor_quotation_lines_VendorQu~" FOREIGN KEY ("VendorQuotationLineId") REFERENCES advance.vendor_quotation_lines ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_commercial_comparison_lines_vendors_VendorId" FOREIGN KEY ("VendorId") REFERENCES advance.vendors ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.quotation_technical_verifications (
    "Id" uuid NOT NULL,
    "VendorQuotationLineId" uuid NOT NULL,
    "VerifierEmployeeId" uuid NOT NULL,
    "ComplianceStatus" character varying(40) NOT NULL,
    "ComplianceSnapshotJson" jsonb NOT NULL,
    "Remarks" character varying(2000) NOT NULL,
    "VerifiedAt" timestamp with time zone NOT NULL,
    "CorrelationId" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_quotation_technical_verifications" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_quote_technical_status" CHECK ("ComplianceStatus" IN ('TechnicallyCompliant','TechnicallyRejected') AND length(trim("Remarks")) > 0),
    CONSTRAINT "FK_quotation_technical_verifications_employees_VerifierEmploye~" FOREIGN KEY ("VerifierEmployeeId") REFERENCES advance.employees ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quotation_technical_verifications_vendor_quotation_lines_Ve~" FOREIGN KEY ("VendorQuotationLineId") REFERENCES advance.vendor_quotation_lines ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.purchase_order_history (
    "Id" uuid NOT NULL,
    "PurchaseOrderId" uuid NOT NULL,
    "Action" character varying(50) NOT NULL,
    "FromStatus" character varying(40) NOT NULL,
    "ToStatus" character varying(40) NOT NULL,
    "RevisionNumber" integer NOT NULL,
    "ActorEmployeeId" uuid NOT NULL,
    "ActorLoginId" character varying(256) NOT NULL,
    "ActorRoleCode" character varying(100) NOT NULL,
    "Reason" character varying(2000) NOT NULL,
    "CorrelationId" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_purchase_order_history" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_purchase_order_history_reason" CHECK (length(trim("Reason")) > 0),
    CONSTRAINT "FK_purchase_order_history_employees_ActorEmployeeId" FOREIGN KEY ("ActorEmployeeId") REFERENCES advance.employees ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_order_history_purchase_orders_PurchaseOrderId" FOREIGN KEY ("PurchaseOrderId") REFERENCES advance.purchase_orders ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.purchase_order_lines (
    "Id" uuid NOT NULL,
    "PurchaseOrderId" uuid NOT NULL,
    "CommercialComparisonLineId" uuid NOT NULL,
    "PurchaseRequisitionLineId" uuid NOT NULL,
    "PurchaseRequirementHandoffId" uuid NOT NULL,
    "ItemId" uuid NOT NULL,
    "LineNumber" integer NOT NULL,
    "ItemCodeSnapshot" character varying(100) NOT NULL,
    "ItemNameSnapshot" character varying(300) NOT NULL,
    "UomSnapshot" character varying(30) NOT NULL,
    "OrderedQuantity" numeric(24,6) NOT NULL,
    "ApprovedOutstandingQuantitySnapshot" numeric(24,6) NOT NULL,
    "UnitRate" numeric(24,6) NOT NULL,
    "CommercialSnapshotJson" jsonb NOT NULL,
    "TaxRuleSnapshotJson" jsonb NOT NULL,
    "TotalPayableValue" numeric(24,6) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_purchase_order_lines" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_purchase_order_line_quantity" CHECK ("OrderedQuantity" > 0 AND "ApprovedOutstandingQuantitySnapshot" > 0 AND "OrderedQuantity" <= "ApprovedOutstandingQuantitySnapshot" AND "UnitRate" >= 0 AND "TotalPayableValue" >= 0),
    CONSTRAINT "FK_purchase_order_lines_commercial_comparison_lines_Commercial~" FOREIGN KEY ("CommercialComparisonLineId") REFERENCES advance.commercial_comparison_lines ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_order_lines_items_ItemId" FOREIGN KEY ("ItemId") REFERENCES advance.items ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_order_lines_purchase_orders_PurchaseOrderId" FOREIGN KEY ("PurchaseOrderId") REFERENCES advance.purchase_orders ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_order_lines_purchase_requirement_handoffs_Purchase~" FOREIGN KEY ("PurchaseRequirementHandoffId") REFERENCES advance.purchase_requirement_handoffs ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_order_lines_purchase_requisition_lines_PurchaseReq~" FOREIGN KEY ("PurchaseRequisitionLineId") REFERENCES advance.purchase_requisition_lines ("Id") ON DELETE RESTRICT
);

CREATE TABLE advance.material_followup_handoffs (
    "Id" uuid NOT NULL,
    "PurchaseOrderId" uuid NOT NULL,
    "PurchaseOrderLineId" uuid NOT NULL,
    "HandoffNumber" character varying(80) NOT NULL,
    "OrderedQuantitySnapshot" numeric(24,6) NOT NULL,
    "Status" character varying(40) NOT NULL,
    "HandoffAt" timestamp with time zone NOT NULL,
    "CorrelationId" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" text NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" text,
    "Version" bigint NOT NULL,
    CONSTRAINT "PK_material_followup_handoffs" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_material_followup_quantity" CHECK ("OrderedQuantitySnapshot" > 0 AND "Status" IN ('PendingFollowUp','InProgress','Completed')),
    CONSTRAINT "FK_material_followup_handoffs_purchase_order_lines_PurchaseOrd~" FOREIGN KEY ("PurchaseOrderLineId") REFERENCES advance.purchase_order_lines ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_material_followup_handoffs_purchase_orders_PurchaseOrderId" FOREIGN KEY ("PurchaseOrderId") REFERENCES advance.purchase_orders ("Id") ON DELETE RESTRICT
);

